// consider
fn f_29(parent: V, receiver: V, args: V, _callee: V) -> Result<V, V> {
    // Hot candidate scoring uses Rust locals, retaining the source's floored
    // Euclidean distances, stick bonus, range limits and strict tie ordering.
    let result: E = (|| {
        let ent = prop(args.clone(), n(0.0))?;
        if !truth(&prop(args, n(1.0))?) || !truth(&ent) {
            return Ok(u());
        }
        let numeric = |value: V| -> Result<f64, Flow> {
            if let Some(number) = value.as_f64() {
                return Ok(number);
            }
            Ok(op("unary", &[s("+"), value])?.as_f64().unwrap_or(f64::NAN))
        };
        let ex = numeric(prop(ent.clone(), s("x"))?)?;
        let ey = numeric(prop(ent.clone(), s("y"))?)?;
        let me = get(&parent, "me")?;
        if truth(&me) {
            let mx = numeric(prop(me.clone(), s("x"))?)?;
            if mx.is_finite() && mx >= 0.0 {
                let my = numeric(prop(me, s("y"))?)?;
                let dx = mx - ex;
                let dy = my - ey;
                let distance = (dx * dx + dy * dy).sqrt().floor();
                let max = numeric(get(&parent, "maxFromMe")?)?;
                if !distance.is_finite() || distance > max {
                    return Ok(u());
                }
            }
        }
        let point = get(&parent, "cords")?;
        let dx = numeric(prop(point.clone(), s("x"))?)? - ex;
        let dy = numeric(prop(point, s("y"))?)? - ey;
        let distance = (dx * dx + dy * dy).sqrt().floor();
        if !distance.is_finite() {
            return Ok(u());
        }
        let stick = numeric(get(&parent, "stick")?)?;
        let fov = numeric(get(&parent, "Fov")?)?;
        let held = prop(receiver, s("targetPlayer"))?;
        let score = if held == ent && distance < fov + stick {
            distance - stick
        } else {
            distance
        };
        if score < numeric(get(&parent, "bestScore")?)? {
            let _ = op("write", &[parent.clone(), s("selected"), ent])?;
            let _ = op("write", &[parent, s("bestScore"), n(score)])?;
        }
        Ok(u())
    })();
    finish(result)
}
