                    let _ = op(
                        "define",
                        &[record.clone(), s("e"), s("value"), entity.clone(), b(true)],
                    )?;
                    let _ = op(
                        "call2",
                        &[cache_set.clone(), cache.clone(), entity, record.clone()],
                    )?;
